from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    # bands = contiguous groups of rows containing non-bg cells
    prow = [any(x != bg for x in g[r]) for r in range(H)]
    bands, cur = [], []
    for r in range(H):
        if prow[r]: cur.append(r)
        elif cur: bands.append(cur); cur = []
    if cur: bands.append(cur)
    if len(bands) < 2:
        return g
    def extent(rows): return max(c for r in rows for c in range(W) if g[r][c] != bg)
    def size(rows): return sum(1 for r in rows for c in range(W) if g[r][c] != bg)
    ref = max(bands, key=lambda b: (extent(b), size(b)))
    for B in bands:
        if B is ref or len(B) != len(ref):
            continue
        band_ext = extent(B)
        for i, r in enumerate(B):
            rr = ref[i]
            cells = [c for c in range(W) if g[r][c] != bg]
            if not cells:
                continue
            last_i = max(cells)
            beyondC = [c for c in range(band_ext + 1, W) if g[rr][c] != bg]
            comp = (len(beyondC) >= 2 and len({c % 2 for c in beyondC}) == 1
                    and beyondC[0] % 2 != last_i % 2)
            for c in range(last_i + 1, W):
                if g[r][c] != bg:
                    continue
                cp = g[rr][c] != bg
                if (not comp and cp) or (comp and not cp):
                    g[r][c] = 1
    return g

